responseSchemaJson:
{
  "type": "object",
  "description": "角色创建大师的核心职责是使用第一人称，基于提供的背景信息创建一个全新的角色档案。所有输出内容必须为简体中文(zh-CN)。",
  "properties": {
    "generatedProfile": {
      "type": "object",
      "description": "[模块一：档案生成] 包含完整的结构化角色档案。使用第一人称‘我’称呼被创建的角色。",
      "properties": {
        "birthAndOrigin": {
          "type": "object",
          "description": "角色的起源信息。这将作为角色的第一条‘基础记录’。",
          "properties": {
            "birthDate": {
              "type": "string",
              "description": "出生日期，格式 'YYYY-MM-DD'。"
            },
            "originDescription": {
              "type": "string",
              "description": "列出角色的父母、家世背景、出生地环境等客观出身事实。"
            }
          },
          "required": [
            "birthDate",
            "originDescription"
          ],
          "propertyOrdering": [
            "birthDate",
            "originDescription"
          ]
        },
        "characterName": {
          "type": "string",
          "description": "所创建角色的中文名称，由`<LatestNews>`中的`User`消息指定。"
        },
        "createdCharacterInfo": {
          "type": "object",
          "description": "包含角色的完整设定和后续背景记忆。",
          "properties": {
            "characterSettings": {
              "type": "object",
              "description": "角色的核心设定。",
              "properties": {
                "MBTI": {
                  "type": "string",
                  "description": "角色的 MBTI 类型。仅填类型，无注释。"
                },
                "bigFivePersonality": {
                  "type": "object",
                  "description": "角色的大五人格特质。仅填评级，无注释。",
                  "properties": {
                    "openness": {
                      "type": "string",
                      "description": "开放性"
                    },
                    "conscientiousness": {
                      "type": "string",
                      "description": "尽责性"
                    },
                    "extraversion": {
                      "type": "string",
                      "description": "外向性"
                    },
                    "agreeableness": {
                      "type": "string",
                      "description": "宜人性"
                    },
                    "neuroticism": {
                      "type": "string",
                      "description": "神经质(强制固定为 '中')"
                    }
                  },
                  "required": [
                    "openness",
                    "conscientiousness",
                    "extraversion",
                    "agreeableness",
                    "neuroticism"
                  ],
                  "propertyOrdering": [
                    "openness",
                    "conscientiousness",
                    "extraversion",
                    "agreeableness",
                    "neuroticism"
                  ]
                },
                "characterArchetypes": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "角色扮演的核心原型。明确告诉AI它在扮演‘什么人’。"
                },
                "keywords": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "概括角色个性/扮演风格的关键词。"
                }
              },
              "required": [
                "MBTI",
                "bigFivePersonality",
                "characterArchetypes",
                "keywords"
              ],
              "propertyOrdering": [
                "MBTI",
                "bigFivePersonality",
                "characterArchetypes",
                "keywords"
              ]
            },
            "initialCharacterMemory": {
              "type": "object",
              "description": "记录出生之后的人生经历。",
              "properties": {
                "memoryEntries": {
                  "type": "array",
                  "description": "按时间顺序记录的关键成长经历。长度为8-16条。",
                  "items": {
                    "type": "object",
                    "properties": {
                      "contextOrDate": {
                        "type": "string",
                        "description": "记忆截止日期，格式 'YYYY-MM-DD'。"
                      },
                      "entryDetail": {
                        "type": "object",
                        "description": "该时间段内事件的结构化摘要。",
                        "properties": {
                          "summary": {
                            "type": "string",
                            "description": "对该时期核心事件的陈述。严禁包含任何主观想法、感受或心理活动。"
                          }
                        },
                        "required": [
                          "summary"
                        ],
                        "propertyOrdering": [
                          "summary"
                        ]
                      }
                    },
                    "required": [
                      "contextOrDate",
                      "entryDetail"
                    ],
                    "propertyOrdering": [
                      "contextOrDate",
                      "entryDetail"
                    ]
                  },
                  "minItems": 8
                }
              },
              "required": [
                "memoryEntries"
              ],
              "propertyOrdering": [
                "memoryEntries"
              ]
            }
          },
          "required": [
            "characterSettings",
            "initialCharacterMemory"
          ],
          "propertyOrdering": [
            "characterSettings",
            "initialCharacterMemory"
          ]
        },
        "publicInfo": {
          "type": "object",
          "description": "角色的公开基本信息。",
          "properties": {
            "name": {
              "type": "string",
              "description": "角色的全名。"
            },
            "gender": {
              "type": "string",
              "description": "角色性别。",
              "enum": [
                "男",
                "女",
                "其他",
                "未知"
              ]
            },
            "appearance": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "角色特色的容貌评价，例如‘倾国倾城’。"
            },
            "hairColor": {
              "type": "string",
              "description": "角色的发色。"
            },
            "identity": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "概括角色广为人知的公开身份的关键词数组。"
            }
          },
          "required": [
            "name",
            "gender",
            "appearance",
            "hairColor",
            "identity"
          ],
          "propertyOrdering": [
            "name",
            "gender",
            "appearance",
            "hairColor",
            "identity"
          ]
        }
      },
      "required": [
        "birthAndOrigin",
        "characterName",
        "createdCharacterInfo",
        "publicInfo"
      ],
      "propertyOrdering": [
        "birthAndOrigin",
        "characterName",
        "createdCharacterInfo",
        "publicInfo"
      ]
    },
    "test": {
      "type": "object",
      "description": "[模块二：测试] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含1对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 1,
          "maxItems": 1
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "generatedProfile",
    "test"
  ],
  "propertyOrdering": [
    "generatedProfile",
    "test"
  ]
}

responseSchemaParserJs:
const rawText = responseJson.candidates[0].content.parts[0].text;
const jsonString = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
const data = JSON.parse(jsonString);
const profile = data.generatedProfile;
const pi = profile.publicInfo;
const cs = profile.createdCharacterInfo.characterSettings;
const bo = profile.birthAndOrigin;
const actions = [
    { type: 'description', content: `【新建角色】${profile.characterName}` },
    { type: 'description', content: `【公开信息】\n姓名: ${pi.name}\n性别: ${pi.gender}\n外貌: ${pi.appearance.join(', ')}\n发色: ${pi.hairColor}\n身份: ${pi.identity.join(', ')}` },
    { type: 'description', content: `【性格设定】\nMBTI: ${cs.MBTI}\n大五人格: O:${cs.bigFivePersonality.openness}, C:${cs.bigFivePersonality.conscientiousness}, E:${cs.bigFivePersonality.extraversion}, A:${cs.bigFivePersonality.agreeableness}, N:${cs.bigFivePersonality.neuroticism}\n原型: ${cs.characterArchetypes.join(', ')}\n关键词: ${cs.keywords.join(', ')}` },
    { type: 'description', content: `【初始记忆 ${bo.birthDate}】\n${bo.originDescription}` }
];
profile.createdCharacterInfo.initialCharacterMemory.memoryEntries.forEach(e => {
    actions.push({ type: 'description', content: `【初始记忆 ${e.contextOrDate}】\n${e.entryDetail.summary}` });
});
return { processedTurnActions: actions, originalData: data };
